    // 4) Count negative nodes inside window
    const cnt = db.logdata.countDocuments({
      game: "mhs",
      playerId: playerId,
      eventKey: { $in: NEGATIVE_KEYS },
      _id: { $gt: windowStartId, $lte: windowEndId }
    });

    cnt === 0 ? "green" : "yellow";
  }
}
